"""Self-contained, offline viewer for a scenario pack (no original game graphics)."""
from html import escape
import json
from pathlib import Path

HTML = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GBA 中后期经典地图 · 30张</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#111720;color:#e5eaf1;font:14px/1.6 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1550px;margin:auto;padding:20px}h1{margin:0 0 8px;font-size:24px}select,button{background:#252f3d;color:inherit;border:1px solid #526077;padding:8px;border-radius:5px;max-width:100%}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px;margin-top:14px}.layout>section{min-width:0}.board{overflow:auto;background:#1c2531;border-radius:8px;padding:10px}svg{display:block;width:100%;min-width:460px;max-height:82vh}aside{min-width:0;background:#1d2633;padding:14px;border-radius:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace}.note{color:#adb9cb}.legend{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.swatch{width:13px;height:13px;display:inline-block;border:1px solid #ccc;margin-right:4px;vertical-align:middle}a{color:#a8caff}.cell{cursor:pointer}.cell:hover{stroke:#fff;stroke-width:1.2}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;border-bottom:1px solid #445268;padding:5px}#stats{margin-top:6px}@media(max-width:850px){.layout{grid-template-columns:minmax(0,1fr)}aside{width:100%}svg{min-width:360px}main{padding:12px}}</style>
<main><h1>GBA 中后期经典地图 · 30张</h1><p class="note">封印、烈火、圣魔各10张。数据来自本地ROM，图中用颜色和符号展示格子，坐标从左上角(0,0)开始。单位是模板；开场、增援、过场和难度变体分别保留，不能把全部组同时当作初始敌军。</p>
<div class="controls"><select id="game"><option value="all">全部三作</option><option value="fe6">封印之剑</option><option value="fe7">烈火之剑</option><option value="fe8">圣魔之光石</option></select><select id="chapter"></select><select id="group"></select><label><input id="showAll" type="checkbox">显示该组其他阵营</label><button id="reset">重置地图变化</button><select id="change"></select></div>
<div id="stats"></div><div class="layout"><section><div class="board" id="map"></div><div class="legend" id="legend"></div><p><a id="json">固定格式 scenario.json</a> · <a id="csv">敌军 CSV</a> · <a href="manifest.json">30张目录与校验值</a></p><p class="note" id="coverage"></p></section><aside><strong id="title"></strong><p id="summary"></p><div id="info">点击地图格子查看地形和敌军。</div><p class="note">职业/物品名称为空时保留原作编号。基础值、成长率、AI和原始记录在JSON中；最终属性仍受原作难度与事件影响。</p></aside></div></main>
<script>const DATA=__DATA__, MANIFEST=__MANIFEST__;
const $=id=>document.getElementById(id);const NS='http://www.w3.org/2000/svg';let current,tiles,selected;
function node(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function gameFilter(){const list=DATA.filter(d=>$('game').value==='all'||d.source.game===$('game').value);$('chapter').replaceChildren(...list.map(d=>new Option(d.name+' / '+d.chapter.number+' / '+d.chapter.route,d.id)));choose()}
function enemies(g){return g.units.filter(u=>u.faction==='enemy').length}
function groupLabel(g){const refs=g.references.map(r=>r.variant?r.kind+':'+r.variant:r.kind);return g.id+' · 敌军模板'+enemies(g)+' · '+[...new Set(refs)].join(', ')}
function choose(){current=DATA.find(d=>d.id===$('chapter').value);tiles=current.map.terrainIds.map(r=>[...r]);const eligible=current.unitGroups.filter(g=>enemies(g));$('group').replaceChildren(...eligible.map(g=>new Option(groupLabel(g),g.id)));const preferred=eligible.find(g=>g.references.some(r=>r.kind==='enemy-table'&&(r.variant==='default'||r.variant==='eliwood-normal')))||eligible.filter(g=>g.references.some(r=>r.kind==='opening'||r.kind==='encounter-table')).sort((a,b)=>enemies(b)-enemies(a))[0]||eligible[0];if(preferred)$('group').value=preferred.id;
$('change').replaceChildren(new Option('选择单组地图变化',''),...current.mapChanges.map(c=>new Option(c.id+' @ '+c.position+' '+c.width+'×'+c.height,c.id)));$('title').textContent=current.name;$('summary').textContent='章节 '+current.chapter.number+' / '+current.chapter.route+' · 内部 '+current.chapter.internalName;const m=MANIFEST.scenarios.find(m=>m.id===current.id);$('json').href=m.file;$('csv').href=m.file.replace('scenario.json','enemies.csv');$('coverage').textContent='静态引用组 '+current.unitGroups.length+' 组，共 '+current.coverage.enemyTemplateCount+' 条敌军模板（含不同难度/事件引用，非同时出场人数）。事件未执行；ASM生成或改变的单位仍需运行时适配。';selected=null;render()}
function render(){const d=current,g=d.unitGroups.find(g=>g.id===$('group').value),w=d.map.width,h=d.map.height,size=18,pad=20;const svg=node('svg',{viewBox:`0 0 ${w*size+pad} ${h*size+pad}`,role:'img','aria-label':d.name});const cells=node('g',{'data-layer':'terrain'});for(let y=0;y<h;y++)for(let x=0;x<w;x++){const tid=tiles[y][x],t=d.terrainCatalog[tid];const rect=node('rect',{x:pad+x*size,y:pad+y*size,width:size,height:size,fill:t.color,stroke:'#252525','stroke-width':.25,'data-x':x,'data-y':y,class:'cell'});rect.addEventListener('click',()=>inspect(x,y));cells.append(rect);if(['#','T','门','箱','梯','柱','裂'].includes(t.glyph))svg.append(node('text',{x:pad+x*size+9,y:pad+y*size+13,'text-anchor':'middle','font-size':10,fill:'#15191f','pointer-events':'none'},t.glyph))}svg.prepend(cells);for(let x=0;x<w;x++)svg.append(node('text',{x:pad+x*size+9,y:14,'font-size':8,'text-anchor':'middle',fill:'#c3d0e4'},x));for(let y=0;y<h;y++)svg.append(node('text',{x:15,y:pad+y*size+12,'font-size':8,'text-anchor':'end',fill:'#c3d0e4'},y));let shown=0;if(g)for(const u of g.units){if(u.positionStatus!=='on-map'||(!enemiesOnly(u)))continue;shown++;const[x,y]=u.position;const marker=node('g',{'data-unit':u.index,cursor:'pointer'});marker.append(node('circle',{cx:pad+x*size+9,cy:pad+y*size+9,r:7,fill:u.faction==='enemy'?'#c62d39':u.faction==='player'?'#276cc4':'#24a057',stroke:'#fff','stroke-width':.7}));marker.append(node('text',{x:pad+x*size+9,y:pad+y*size+12,'text-anchor':'middle','font-size':7,fill:'#fff'},u.index+1));marker.addEventListener('click',()=>inspect(x,y));svg.append(marker)}$('map').replaceChildren(svg);$('legend').replaceChildren(...Object.values(d.terrainCatalog).map(t=>{const n=document.createElement('span');const sw=document.createElement('i');sw.className='swatch';sw.style.background=t.color;n.append(sw,document.createTextNode(t.id+': '+t.label));return n}));$('stats').textContent=d.map.width+' × '+d.map.height+' · 当前组显示 '+shown+' 个地图内单位 · '+d.source.gameCode;if(selected)inspect(...selected)}
function enemiesOnly(u){return $('showAll').checked||u.faction==='enemy'}
function inspect(x,y){selected=[x,y];const d=current,g=d.unitGroups.find(g=>g.id===$('group').value),tid=tiles[y][x];const found=(g?.units||[]).filter(u=>u.position?.[0]===x&&u.position?.[1]===y&&enemiesOnly(u));const lines=[`坐标 (${x}, ${y})`,`地形 ${tid}: ${d.terrainCatalog[tid].label}`];for(const u of found){lines.push('',`单位模板 #${u.index+1} / ${u.faction}`,`角色 ${u.characterSymbol||u.characterId}`,`职业 ${u.classSymbol||u.effectiveClassId}`,`模板等级 ${u.level} / 自动升级 ${u.autolevel}`,`入场 ${u.entryPosition} → 终点 ${u.position}`,`物品 ${u.itemIds.map(i=>d.itemCatalog[i]?.symbol||i).join(', ')}`,`AI ${u.aiBytes.map(v=>v.toString(16).padStart(2,'0')).join(' ')}`,u.sourceAddress)}const pre=document.createElement('pre');pre.textContent=lines.join('\n');$('info').replaceChildren(pre)}
$('game').onchange=gameFilter;$('chapter').onchange=choose;$('group').onchange=()=>{selected=null;render()};$('showAll').onchange=render;$('reset').onclick=()=>{tiles=current.map.terrainIds.map(r=>[...r]);$('change').value='';render()};$('change').onchange=()=>{tiles=current.map.terrainIds.map(r=>[...r]);const c=current.mapChanges.find(c=>c.id===$('change').value);if(c)for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){const v=c.terrainIds[y][x];if(v!==null)tiles[c.position[1]+y][c.position[0]+x]=v}render()};gameFilter();</script></html>'''


def write_pack_preview(documents, manifest, out: Path):
    # Embed view data so double-clicking the HTML works under file:// without fetch/CORS.
    view = [{key: d[key] for key in ['id', 'name', 'chapter', 'source', 'map', 'terrainCatalog',
                                    'unitGroups', 'mapChanges', 'itemCatalog', 'coverage']} for d in documents]
    data = json.dumps(view, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    index = json.dumps(manifest, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    (out / 'index.html').write_text(HTML.replace('__DATA__', data).replace('__MANIFEST__', index), encoding='utf-8')
    lines = ['# GBA中后期经典地图：30张固定格式素材', '',
             '从用户提供的三份GBA文件直接采集，封印、烈火、圣魔各10张。坐标为左上角零基`[x,y]`，矩阵为`[y][x]`。', '',
             '本轮只选可正常编队的常规战斗、撤退或占领图；少量单位试炼及坚守、护送、收集、孵化等特殊任务已排除。', '',
             '- [离线交互预览](index.html)：选作品、章节、敌军模板组，点击格子查看等级/装备/AI。',
             '- [总目录与文件校验值](manifest.json)。',
             '- [固定格式与项目读取方式](../../../tools/gba/README.md)。',
             '- [项目接入TODO](../../../docs/24-classic-scenarios-integration-todo.md)。', '',
             '敌军数是去重单位组中的模板条目数，包含难度、开场、增援、过场等静态引用，并非同时出场人数。封印/烈火另记录主路线普通难度的初始表数量；圣魔保留开场脚本引用证据。未执行事件、ASM、随机数及原作存档。', '',
             '| 作品 | 章号/路线 | 地图 | 尺寸 | 敌军模板 | 初始表敌军 | 文件 |', '| --- | --- | --- | --- | ---: | ---: | --- |']
    for entry, document in zip(manifest['scenarios'], documents):
        primary = document['coverage']['primaryEnemyTemplateCount']
        lines.append(f"| {document['source']['game']} | {entry['chapter']} / {entry['route']} | {entry['name']} | {entry['width']}×{entry['height']} | {entry['enemyTemplates']} | {primary if primary is not None else '脚本引用分组'} | [JSON]({entry['file']}) · [敌军CSV]({entry['file'].replace('scenario.json', 'enemies.csv')}) |")
    (out / 'README.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
